#include <bits/stdc++.h>
using namespace std;
const int MAXN=270005;
int n,m,k,mod;
int f[19][MAXN];
vector<long long> g;
int cnt[MAXN];

int modify(int x){
    if(x<0) return x+mod;
    if(x>=mod) return x-mod;
    return x;
}

void combine(int &x, int y){
    x=modify(x+y);
}

int fast_pow(int base,int exp){
    int res=1;
    while(exp){
        if(exp&1) res=1LL*res*base%mod;
        base=1LL*base*base%mod;
        exp>>=1;
    }
    return res;
}

int fact[MAXN], inv_fact[MAXN];

void prepare(int n){
    fact[0]=1;
    for(int i=1;i<=n;i++) fact[i]=1LL*fact[i-1]*i%mod;
    inv_fact[n]=fast_pow(fact[n],mod-2);
    for(int i=n-1;i>=0;i--) inv_fact[i]=1LL*inv_fact[i+1]*(i+1)%mod;
}

void transform(int *arr,int size,int h){
    for(int p=1; p<size; p<<=1)
        for(int i=0; i<size; i+=p<<1)
            for(int k=i; k<i+p; k++)
                combine(arr[k+p], h*arr[k]);
}

int l;
vector<long long> operator*(vector<long long> &A, vector<long long> &B){
    static vector<long long> C; C.clear(); C.resize(l+1);
    for(int i=0; i<=l; i++)
        for(int j=0; j<=l-i; j++)
            C[i+j]+=A[i]*B[j];
    for(int i=0; i<=l; i++) C[i]%=mod;
    return C;
}

vector<long long> series_power(vector<long long> A, int k){
    static vector<long long> C; C.clear(); C.resize(l+1);
    C[0]=1;
    while(k){
        if(k&1) C=C*A;
        A=A*A;
        k>>=1;
    }
    return C;
}

int main(){
#ifdef pig
    freopen("C.in","r",stdin);
    freopen("C.out","w",stdout);
#endif
    cin>>n>>k>>mod;
    prepare(n);
    if(n&1){
        cout<<fast_pow(k,n);
        return 0;
    }
    m=1; while(m<=n) m<<=1; l++;
    for(int i=0; i<m; i++) cnt[i]=__builtin_popcount(i);
    prepare(m);
    for(int i=0; i<m; i++){
        f[cnt[i]][i]=inv_fact[i];
    }
    for(int i=0; i<l; i++) transform(f[i], m, 1);
    g.resize(l+1);
    for(int s=0; s<m; s++){
        for(int i=0; i<=l; i++) g[i]=f[i][s];
        g=series_power(g,k);
        for(int i=0; i<=l; i++) f[i][s]=g[i];
    }
    transform(f[cnt[n]], m, -1);
    cout<<modify(fast_pow(k,n)-1LL*f[cnt[n]][n]*fact[n]%mod);
    return 0;
}
